contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint v1, uint v2, uint v3) public payable {
        bool r1;
        c.SetMinSum(v1); bool __rev0 = __ESBMC_reverted(); if (__rev0) { r1 = true; } else { r1 = false; }
        require(!r1);

        bool r2;
        c.SetMinSum(v2); bool __rev1 = __ESBMC_reverted(); if (__rev1) { r2 = true; } else { r2 = false; }

        bool r3;
        c.SetMinSum(v3); bool __rev2 = __ESBMC_reverted(); if (__rev2) { r3 = true; } else { r3 = false; }

        uint finalMinSum = c.MinSum(); if (__ESBMC_reverted()) return;

        assert(r1 || r2 || r3 || finalMinSum == v3);
    }
}

