pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 v1, uint256 v2, uint256 v3) internal {
        bool r1;
        try c.SetMinSum(v1) { r1 = false; } catch { r1 = true; }
        vm.assume(!r1);
        bool r2;
        try c.SetMinSum(v2) { r2 = false; } catch { r2 = true; }
        bool r3;
        try c.SetMinSum(v3) { r3 = false; } catch { r3 = true; }
        uint256 finalMinSum;
        try c.MinSum() returns (uint256 __r) { finalMinSum = __r; } catch { return; }
        assertTrue(r1 || r2 || r3 || finalMinSum == v3);
    }

    function testFuzz_run(uint256 v1, uint256 v2, uint256 v3) public {
        _run(v1, v2, v3);
    }

    receive() external payable {}
}
